-- QHS Commerce ONLY. Apply to a new, dedicated Supabase project.
begin;
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','sales','content','warehouse','customer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.app_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function public.has_role(roles public.app_role[]) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.profiles where id=auth.uid() and role=any(roles)); $$;
revoke all on function public.has_role(public.app_role[]) from public;
grant execute on function public.has_role(public.app_role[]) to anon,authenticated;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger new_auth_user after insert on auth.users for each row execute function public.handle_new_user();
create table public.categories(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), parent_id uuid references public.categories(id), description text not null default '', seo_content text not null default '', status text not null default 'draft' check(status in ('draft','published','archived')), seo_title text not null default '', meta_description text not null default '', canonical_url text not null default '', og_image text not null default '', noindex boolean not null default false, check(parent_id is distinct from id));
create table public.brands(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, slug text not null unique, status text not null default 'draft' check(status in ('draft','published','archived')), logo text not null default '');
create table public.products(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), name text not null, slug text not null unique, sku text not null unique, model text not null default '', category_id uuid not null references public.categories(id), brand_id uuid references public.brands(id) on delete set null, short_description text not null default '', full_description text not null default '', featured_image text not null default '', sales_type text not null default 'QUOTE' check(sales_type in ('DIRECT','QUOTE','PROJECT')), price numeric(16,2) check(price>=0), sale_price numeric(16,2) check(sale_price is null or (sale_price>=0 and price is not null and sale_price<=price)), vat numeric(5,2) not null default 0 check(vat>=0 and vat<=100), stock_status text not null default 'contact' check(stock_status in ('in_stock','out_of_stock','contact')), stock_quantity integer check(stock_quantity>=0), status text not null default 'draft' check(status in ('draft','published','archived')), featured boolean not null default false, is_demo boolean not null default false, warranty text not null default '', application text not null default '', capacity text not null default '', division text not null default '', specs jsonb not null default '[]' check(jsonb_typeof(specs)='array'), gallery jsonb not null default '[]' check(jsonb_typeof(gallery)='array'), documents jsonb not null default '[]' check(jsonb_typeof(documents)='array'), videos jsonb not null default '[]' check(jsonb_typeof(videos)='array'), seo_title text not null default '', meta_description text not null default '', canonical_url text not null default '', og_image text not null default '', noindex boolean not null default false, search_vector tsvector generated always as (to_tsvector('simple',name||' '||sku||' '||model||' '||short_description||' '||full_description||' '||capacity||' '||application||' '||specs::text)) stored, check(sales_type<>'DIRECT' or price is not null));
create table public.product_variants(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references public.products(id) on delete cascade, sku text not null unique, name text not null, attributes jsonb not null default '{}', price numeric(16,2) check(price>=0), stock_quantity integer not null default 0 check(stock_quantity>=0));
create table public.related_products(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references public.products(id) on delete cascade, related_product_id uuid not null references public.products(id) on delete cascade, relation text not null default 'related' check(relation in ('related','accessory')), unique(product_id,related_product_id), check(product_id<>related_product_id));
create table public.customers(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid unique references auth.users(id), name text not null, email text, phone text, company text, tax_code text, assigned_to uuid references public.profiles(id));
create table public.leads(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, phone text not null, email text, company text, province text, message text not null, product_id uuid references public.products(id) on delete set null, type text not null default 'contact' check(type in ('contact','quote','survey','callback')), source text not null default 'Direct' check(source in ('Organic','Google Ads','Facebook','Direct','Referral','Other')), status text not null default 'NEW', assigned_to uuid references public.profiles(id), customer_id uuid references public.customers(id), utm_source text, utm_medium text, utm_campaign text, utm_content text, utm_term text, landing_page text, referrer text, consent_at timestamptz);
create table public.customer_contacts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), customer_id uuid not null references public.customers(id) on delete cascade, name text not null, email text, phone text, title text);
create table public.opportunities(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), customer_id uuid references public.customers(id), lead_id uuid references public.leads(id), title text not null, value numeric(16,2) check(value>=0), stage text not null default 'NEW' check(stage in ('NEW','CONTACTED','QUALIFIED','SURVEY','QUOTED','NEGOTIATION','WON','LOST')), probability integer check(probability between 0 and 100), expected_close_date date, assigned_to uuid references public.profiles(id));
create table public.opportunity_activities(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, created_by uuid references public.profiles(id), type text not null check(type in ('CALL','MEETING','MESSAGE','EMAIL','NOTE','TASK')), description text not null, occurred_at timestamptz not null default now());
create table public.quotations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), quotation_number text not null unique, customer_id uuid not null references public.customers(id), opportunity_id uuid references public.opportunities(id), status text not null default 'DRAFT' check(status in ('DRAFT','SENT','ACCEPTED','REJECTED','EXPIRED')), subtotal numeric(16,2) not null default 0 check(subtotal>=0), tax numeric(16,2) not null default 0 check(tax>=0), discount numeric(16,2) not null default 0 check(discount>=0), total numeric(16,2) not null default 0 check(total>=0), notes text, valid_until date);
create table public.quotation_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), quotation_id uuid not null references public.quotations(id) on delete cascade, product_id uuid references public.products(id) on delete set null, description text not null, quantity numeric(12,3) not null check(quantity>0), unit_price numeric(16,2) not null check(unit_price>=0), discount numeric(16,2) not null default 0 check(discount>=0), tax numeric(16,2) not null default 0 check(tax>=0), total numeric(16,2) not null check(total>=0));
create table public.tasks(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), title text not null, customer_id uuid references public.customers(id), opportunity_id uuid references public.opportunities(id), assigned_to uuid references public.profiles(id), due_at timestamptz, status text not null default 'OPEN' check(status in ('OPEN','DONE','CANCELLED')));
create table public.notes(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), customer_id uuid references public.customers(id), opportunity_id uuid references public.opportunities(id), created_by uuid references public.profiles(id), content text not null);
create table public.carts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid references auth.users(id), anonymous_token_hash text unique, check(user_id is not null or anonymous_token_hash is not null));
create table public.cart_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), cart_id uuid not null references public.carts(id) on delete cascade, product_id uuid not null references public.products(id), variant_id uuid references public.product_variants(id), quantity integer not null check(quantity between 1 and 999), unique nulls not distinct(cart_id,product_id,variant_id));
create table public.shipping_addresses(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid not null references auth.users(id), full_name text not null, phone text not null, province text not null, district text, ward text not null, address text not null);
create table public.orders(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_number text not null unique, customer_id uuid references public.customers(id), user_id uuid references auth.users(id), status text not null default 'PENDING' check(status in ('PENDING','AWAITING_PAYMENT','PAID','PROCESSING','SHIPPING','COMPLETED','CANCELLED','REFUNDED')), customer_snapshot jsonb not null, shipping_snapshot jsonb not null, subtotal numeric(16,2) not null check(subtotal>=0), tax numeric(16,2) not null default 0 check(tax>=0), shipping_fee numeric(16,2) not null default 0 check(shipping_fee>=0), discount numeric(16,2) not null default 0 check(discount>=0), total numeric(16,2) not null check(total>=0), currency text not null default 'VND', notes text);
create table public.order_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, sku text not null, variant_snapshot jsonb, quantity integer not null check(quantity>0), unit_price numeric(16,2) not null check(unit_price>=0), tax numeric(16,2) not null default 0 check(tax>=0), total numeric(16,2) not null check(total>=0));
create table public.payments(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_id uuid not null references public.orders(id), provider text not null check(provider in ('COD','BANK_TRANSFER','PAYOS')), provider_reference text unique, idempotency_key text not null unique, amount numeric(16,2) not null check(amount>=0), currency text not null default 'VND', status text not null default 'PENDING' check(status in ('PENDING','PAID','FAILED','REFUNDED')), verified_at timestamptz);
create table public.payment_events(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), provider text not null, event_id text not null, payment_id uuid references public.payments(id), payload jsonb not null, unique(provider,event_id));
create table public.order_status_history(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_id uuid not null references public.orders(id), status text not null, created_by uuid references public.profiles(id), note text);
create table public.post_categories(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, slug text not null unique, status text not null default 'draft' check(status in ('draft','published','archived')));
create table public.posts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), title text not null, slug text not null unique, excerpt text not null default '', content text not null default '', featured_image text not null default '', author_id uuid references public.profiles(id), category_id uuid references public.post_categories(id), published_at timestamptz, status text not null default 'draft' check(status in ('draft','published','archived')), seo_title text not null default '', meta_description text not null default '', canonical_url text not null default '', og_image text not null default '', noindex boolean not null default false, is_demo boolean not null default false);
create table public.pages(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), title text not null, slug text not null unique, excerpt text not null default '', content text not null default '', featured_image text not null default '', status text not null default 'draft' check(status in ('draft','published','archived')), seo_title text not null default '', meta_description text not null default '', canonical_url text not null default '', og_image text not null default '', noindex boolean not null default false, is_demo boolean not null default false);
create table public.projects(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), title text not null, slug text not null unique, excerpt text not null default '', content text not null default '', featured_image text not null default '', customer_public_name text, publication_consent boolean not null default false, location text, industry text, requirement text, solution text, implementation text, result text, project_date date, gallery jsonb not null default '[]', videos jsonb not null default '[]', status text not null default 'draft' check(status in ('draft','published','archived')), seo_title text not null default '', meta_description text not null default '', canonical_url text not null default '', og_image text not null default '', noindex boolean not null default false, is_demo boolean not null default false, check(status<>'published' or publication_consent=true or is_demo=true));
create table public.project_products(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), project_id uuid not null references public.projects(id) on delete cascade, product_id uuid not null references public.products(id), unique(project_id,product_id));
create table public.faqs(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), question text not null, answer text not null, category_id uuid references public.categories(id), product_id uuid references public.products(id), status text not null default 'draft' check(status in ('draft','published','archived')));
create table public.audit_logs(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), actor_id uuid references auth.users(id), table_name text not null, record_id uuid, action text not null, changed_fields text[]);
create table public.settings(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), key text not null unique, value jsonb not null default '{}');
create table public.rate_limits(id uuid primary key default gen_random_uuid(), key text not null unique, window_start timestamptz not null, count integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index products_search_idx on public.products using gin(search_vector);
create index products_category_idx on public.products(category_id);
create index products_brand_idx on public.products(brand_id);
create index products_status_idx on public.products(status);
create index categories_parent_idx on public.categories(parent_id);
create index leads_status_idx on public.leads(status);
create index leads_assigned_idx on public.leads(assigned_to);
create index orders_user_idx on public.orders(user_id);
create index opportunities_stage_idx on public.opportunities(stage);
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
alter table public.profiles enable row level security;
create trigger touch_profiles before update on public.profiles for each row execute function public.set_updated_at();
create index profiles_created_idx on public.profiles(created_at);
create policy admin_all on public.profiles for all to authenticated using(public.has_role(array['admin']::public.app_role[])) with check(public.has_role(array['admin']::public.app_role[]));
