create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit_logs(actor_id,table_name,record_id,action,changed_fields) values(auth.uid(),TG_TABLE_NAME,coalesce(new.id,old.id),TG_OP,array(select jsonb_object_keys(coalesce(to_jsonb(new),to_jsonb(old))))); if TG_OP='DELETE' then return old; end if; return new; end; $$;
create trigger audit_products after insert or update or delete on public.products for each row execute function public.audit_change();
create trigger audit_categories after insert or update or delete on public.categories for each row execute function public.audit_change();
create trigger audit_brands after insert or update or delete on public.brands for each row execute function public.audit_change();
create trigger audit_profiles after insert or update or delete on public.profiles for each row execute function public.audit_change();
create trigger audit_posts after insert or update or delete on public.posts for each row execute function public.audit_change();
create trigger audit_projects after insert or update or delete on public.projects for each row execute function public.audit_change();
create trigger audit_leads after insert or update or delete on public.leads for each row execute function public.audit_change();
create trigger audit_orders after insert or update or delete on public.orders for each row execute function public.audit_change();
create trigger audit_payments after insert or update or delete on public.payments for each row execute function public.audit_change();
create function public.consume_rate_limit(p_key text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path='' as $$ declare hits integer; begin insert into public.rate_limits(key,window_start,count) values(p_key,now(),1) on conflict(key) do update set count=case when public.rate_limits.window_start<now()-make_interval(secs=>p_window_seconds) then 1 else public.rate_limits.count+1 end,window_start=case when public.rate_limits.window_start<now()-make_interval(secs=>p_window_seconds) then now() else public.rate_limits.window_start end returning count into hits; return hits<=p_limit; end; $$;
revoke all on function public.consume_rate_limit(text,integer,integer) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer,integer) to service_role;
